using Dotnetarium.Analyzers.Taint;
using Dotnetarium.Analyzers.Cryptography;

namespace Dotnetarium.Analyzers.Tests;

public sealed class ServerComponentTests
{
    [Theory]
    [InlineData("Probe_razor.g.cs", 1)]
    [InlineData("Unrelated.g.cs", 0)]
    public async Task Grpc_configuration_checks_only_inspect_mapped_Razor_user_code(string file, int expected)
    {
        var source = """
            // <auto-generated/>
            using Grpc.Net.Client;
            using Grpc.Core;
            public class Demo {
                public void Run() {
            #line 12 "Probe.razor"
                    _ = GrpcChannel.ForAddress("http://remote.example", new GrpcChannelOptions {
                        UnsafeUseInsecureChannelCallCredentials = true,
                        Credentials = ChannelCredentials.Create(ChannelCredentials.Insecure,
                            CallCredentials.FromInterceptor((context, metadata) => System.Threading.Tasks.Task.CompletedTask))
                    });
            #line default
                }
            }
            """;
        var diagnostics = await FrameworkProbe.Analyze(source, new GrpcConfigurationAnalyzer(), filePath: file);
        Assert.Equal(expected, diagnostics.Count(d => d.Id == "DNA0019"));
    }

    [Theory]
    [InlineData("$\"{Root}/api?q={System.Uri.EscapeDataString(input)}\"", 0)]
    [InlineData("$\"{Root}/api?q={input}\"", 1)]
    [InlineData("$\"{input}/api?q={System.Uri.EscapeDataString(input)}\"", 1)]
    [InlineData("$\"{System.Uri.EscapeDataString(input)}/api\"", 1)]
    public async Task Encoded_query_data_does_not_select_an_untainted_request_authority(string destination, int expected)
    {
        var source = """
            using Microsoft.AspNetCore.Mvc;
            using System.Net.Http;
            public class Demo : ControllerBase {
                public string Root { get; set; } = "https://trusted.example";
                public async System.Threading.Tasks.Task Run(string input) {
                    using var client = new HttpClient();
                    await client.GetAsync(
            """ + destination + """
                    );
                }
            }
            """;
        Assert.Equal(expected, (await FrameworkProbe.Analyze(source, new ServerSideRequestForgeryTaintAnalyzer())).Count(d => d.Id == "DNA0011"));
    }

    [Theory]
    [InlineData(false, 1)]
    [InlineData(true, 0)]
    public async Task Child_callbacks_inherit_a_source_defined_parent_server_mode(bool unknownOverride, int expected)
    {
        var source = """
            using Microsoft.AspNetCore.Components;
            using Microsoft.AspNetCore.Components.Web;
            using Microsoft.AspNetCore.Components.Rendering;
            using System.Diagnostics;
            [Parent.__PrivateComponentRenderMode]
            public sealed class Parent : ComponentBase {
                private sealed class __PrivateComponentRenderModeAttribute : RenderModeAttribute {
                    public override IComponentRenderMode Mode => RenderMode.InteractiveServer;
                }
                protected override void BuildRenderTree(RenderTreeBuilder builder) {
                    builder.OpenComponent<Child>(0); builder.CloseComponent();
                }
            }
            public sealed class Child : ComponentBase {
                private string input = "fixed";
                private void Run() => Process.Start(new ProcessStartInfo("cmd.exe", "/c echo " + input));
                protected override void BuildRenderTree(RenderTreeBuilder builder) {
                    builder.OpenElement(0, "input");
                    builder.AddAttribute(1, "onchange", EventCallback.Factory.CreateBinder<string>(this, value => input = value, input));
                    builder.CloseElement();
                    builder.OpenElement(2, "button");
                    builder.AddAttribute(3, "onclick", EventCallback.Factory.Create(this, Run));
                    builder.CloseElement();
                }
            }
            """;
        if (unknownOverride) source = source.Replace("public sealed class Child :", "[UnknownMode] public sealed class Child :") + "\npublic sealed class UnknownModeAttribute : RenderModeAttribute { public override IComponentRenderMode Mode => null!; }";
        Assert.Equal(expected, (await FrameworkProbe.Analyze(source, new CommandInjectionTaintAnalyzer())).Count(d => d.Id == "DNA0002"));
    }

    [Theory]
    [InlineData("RenderMode.InteractiveServer", 1)]
    [InlineData("RenderMode.InteractiveAuto", 1)]
    [InlineData("RenderMode.InteractiveWebAssembly", 1)]
    [InlineData("new InteractiveWebAssemblyRenderMode(false)", 0)]
    public async Task Query_input_can_reach_server_sinks_during_lifecycle_but_not_client_only_rendering(string mode, int expected)
    {
        var source = """
            using Microsoft.AspNetCore.Components;
            using Microsoft.AspNetCore.Components.Web;
            using System.Diagnostics;
            [Demo.__PrivateComponentRenderMode]
            public sealed class Demo : ComponentBase {
                [SupplyParameterFromQuery] public string Input { get; set; } = "fixed";
                private sealed class __PrivateComponentRenderModeAttribute : RenderModeAttribute {
                    public override IComponentRenderMode Mode =>
            """ + mode + """
                    ;
                }
                protected override void OnInitialized() => Process.Start(new ProcessStartInfo("cmd.exe", "/c echo " + Input));
            }
            """;
        var diagnostics = await FrameworkProbe.Analyze(source, new CommandInjectionTaintAnalyzer());
        Assert.Equal(expected, diagnostics.Count(d => d.Id == "DNA0002"));
    }

    [Theory]
    [InlineData("false", 1)]
    [InlineData("true", 0)]
    public async Task Xss_encoding_does_not_sanitize_SQL_component_state(string encodeForHtml, int expectedXss)
    {
        var assignment = encodeForHtml == "true" ? "System.Net.WebUtility.HtmlEncode(value)" : "value";
        var source = """
            using Microsoft.AspNetCore.Components;
            using Microsoft.AspNetCore.Components.Web;
            using Microsoft.AspNetCore.Components.Rendering;
            using Microsoft.Data.SqlClient;
            [Demo.__PrivateComponentRenderMode]
            public sealed class Demo : ComponentBase {
                private string input = "fixed";
                private sealed class __PrivateComponentRenderModeAttribute : RenderModeAttribute {
                    public override IComponentRenderMode Mode => RenderMode.InteractiveServer;
                }
                private void Run() { using var command = new SqlCommand("SELECT '" + input + "'"); }
                protected override void BuildRenderTree(RenderTreeBuilder builder) {
                    builder.OpenElement(0, "input");
                    builder.AddAttribute(1, "onchange", EventCallback.Factory.CreateBinder<string>(this, value => input =
            """ + assignment + """
                    , input));
                    builder.CloseElement();
                    builder.OpenElement(2, "button");
                    builder.AddAttribute(3, "onclick", EventCallback.Factory.Create(this, Run));
                    builder.CloseElement();
                    builder.AddMarkupContent(4, input);
                }
            }
            """;
        Assert.Single((await FrameworkProbe.Analyze(source, new SqlInjectionTaintAnalyzer())).Where(d => d.Id == "DNA0001"));
        Assert.Equal(expectedXss, (await FrameworkProbe.Analyze(source, new XssTaintAnalyzer())).Count(d => d.Id == "DNA0003"));
    }

    [Theory]
    [InlineData("RenderMode.InteractiveServer", 1)]
    [InlineData("new InteractiveServerRenderMode(false)", 1)]
    [InlineData("RenderMode.InteractiveAuto", 1)]
    [InlineData("RenderMode.InteractiveWebAssembly", 0)]
    [InlineData("new InteractiveWebAssemblyRenderMode(false)", 0)]
    [InlineData("null", 0)]
    public async Task Browser_input_reaches_commands_only_with_server_execution_evidence(string mode, int expected)
    {
        var source = """
            using Microsoft.AspNetCore.Components;
            using Microsoft.AspNetCore.Components.Web;
            using Microsoft.AspNetCore.Components.Rendering;
            using System.Diagnostics;
            [Demo.__PrivateComponentRenderMode]
            public sealed class Demo : ComponentBase {
                private string input = "fixed";
                private void Run() => Process.Start(new ProcessStartInfo("cmd.exe", "/c echo " + input));
                private sealed class __PrivateComponentRenderModeAttribute : RenderModeAttribute {
                    private static IComponentRenderMode ModeImpl =>
            """ + mode + """
                    ; public override IComponentRenderMode Mode => ModeImpl;
                }
                protected override void BuildRenderTree(RenderTreeBuilder builder) {
                    builder.OpenElement(0, "input");
                    builder.AddAttribute(1, "onchange", EventCallback.Factory.CreateBinder<string>(this, value => input = value, input));
                    builder.CloseElement();
                    builder.OpenElement(2, "button");
                    builder.AddAttribute(3, "onclick", EventCallback.Factory.Create(this, Run));
                    builder.CloseElement();
                }
            }
            """;
        var diagnostics = await FrameworkProbe.Analyze(source, new CommandInjectionTaintAnalyzer());
        Assert.Equal(expected, diagnostics.Count(d => d.Id == "DNA0002"));
        Assert.DoesNotContain(diagnostics, d => d.Id == "DNA9000");
    }

    [Theory]
    [InlineData("_ = DES.Create();", "DNA0013")]
    [InlineData("using var aes = Aes.Create(); aes.Mode = CipherMode.ECB;", "DNA0014")]
    [InlineData("_ = Rfc2898DeriveBytes.Pbkdf2(\"p\", new byte[16], 1000, HashAlgorithmName.SHA256, 32);", "DNA0016")]
    public async Task Crypto_rules_analyze_mapped_Razor_but_skip_other_generated_code(string statement, string id)
    {
        var source = """
            // <auto-generated/>
            using System.Security.Cryptography;
            public class Demo {
                public void Run() {
            #line 10 "Probe.razor"
            """ + "\n" + statement + "\n" + """
            #line default
                }
            }
            """;
        var razor = await FrameworkProbe.Analyze(source, new CryptographyAnalyzer(), filePath: "Probe_razor.g.cs");
        var finding = Assert.Single(razor.Where(d => d.Id == id));
        Assert.Equal("Probe.razor", finding.Location.GetMappedLineSpan().Path);
        Assert.Empty(await FrameworkProbe.Analyze(source, new CryptographyAnalyzer(), filePath: "Unrelated.g.cs"));
    }
}
